//! Finish publication after the first publisher checked its own metadata link too early.
use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},process::Command,collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/compact-tree176";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-31-compact-tree176";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn walk(p:&Path,v:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_dir(){walk(&e.path(),v)}else{assert!(e.file_type().unwrap().is_file());v.push(e.path())}}}
fn main(){let mut archives=BTreeMap::new();for name in["source","workflow","receipts","counters","memory-audit"]{let file=format!("{D}/artifacts/{name}.tar.gz");let listing=Command::new("tar").args(["-tzf",&file]).output().unwrap();assert!(listing.status.success());let text=String::from_utf8(listing.stdout).unwrap();let members=text.lines().filter(|s|!s.ends_with('/')).collect::<Vec<_>>();let roundtrip=format!("{R}/roundtrip-{name}");let mut actual=vec![];walk(Path::new(&roundtrip),&mut actual);assert_eq!(members.len(),actual.len());for member in &members{assert!(!member.starts_with('/')&&!member.split('/').any(|s|s==".."));assert_eq!(hash(Path::new(&roundtrip).join(member)),hash(Path::new(R).join(member)));}archives.insert(name,json!({"members":members.len(),"sha256":hash(&file),"all_bytes_roundtrip_verified":true}));}
let raw:Value=serde_json::from_slice(&fs::read(format!("{R}/latency-analysis.json")).unwrap()).unwrap();let review:Value=serde_json::from_slice(&fs::read(format!("{R}/review.json")).unwrap()).unwrap();assert_eq!(raw["gate_passed"],false);assert_eq!(review["review_passed"],true);assert_eq!(review["command_receipts_verified"],1185);let failure=fs::read_to_string(format!("{R}/publish.log")).unwrap();assert!(failure.contains("artifacts/publication.json"));fs::copy(format!("{R}/publish.log"),format!("{D}/artifacts/publish-initial.log")).unwrap();fs::copy(file!(),format!("{D}/artifacts/finish.rs")).unwrap();
fs::write(format!("{D}/artifacts/publication.json"),serde_json::to_vec_pretty(&json!({"archives":archives,"actual_final_link_flags_verified_by_first_publisher":true,"primary_commands_reviewed":1185,"primary_callers":1164,"additional_resource_only_callers":7,"memory_parent_source_sha256":hash(format!("{R}/memory-audit.rs")),"memory_parent_binary_sha256":hash(format!("{R}/memory-audit-helper")),"all_primary_pins_unchanged_after_resource_audit":true,"native_field_tests":37,"native_core_tests":129,"publication_repair":"Initial publisher completed archive byte roundtrips, then checked its own publication.json link before writing that file. This helper verifies existing archives, writes metadata before link validation, and preserves the original failure/source. No recapture, test or analysis changes.","gate_passed":false,"adopted":false,"production_changed":false,"new_proofs":0,"proof_ledger":27851,"goal_achieved":false})).unwrap()).unwrap();
let doc=fs::read_to_string(format!("{D}/README.md")).unwrap();let mut rest=doc.as_str();let mut links=0;let mut external=0;while let Some(i)=rest.find("]("){rest=&rest[i+2..];let j=rest.find(')').unwrap();let link=&rest[..j];if link.starts_with("https://"){assert_eq!(link,"https://www.kernel.org/doc/html/v6.12/filesystems/proc.html");external+=1;}else{assert!(Path::new(D).join(link).is_file(),"{link}");links+=1;}rest=&rest[j+1..];}assert_eq!((links,external),(16,1));let mut all=vec![];walk(Path::new(D),&mut all);all.sort();let mut sums=String::new();for p in all{let rel=p.strip_prefix(D).unwrap();if rel!=Path::new("SHA256SUMS"){sums.push_str(&format!("{}  {}\n",hash(&p),rel.display()));}}fs::write(format!("{D}/SHA256SUMS"),sums).unwrap();println!("Recoveredpublication-orderfailure;5archivesbyteverified;16locallinks+1officialdoclinkPASS;rawdataandgateunchanged");}
